const input = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
let darioWins = 0;

for (let i = 0; i < n; i++) {
  const d = input[1 + 2 * i];
  const x = input[2 + 2 * i];
  const difference = (x - d + 5) % 5;

  if (difference === 1 || difference === 2) darioWins++;
}

console.log(darioWins > n / 2 ? 'dario' : 'xerxes');
